## Mitigation Recommendations

### Immediate Fix:
```solidity
// Use SafeMath or explicit overflow checks
function updateSnapshot(Operator memory operator) internal view {
    uint32 currentBlock = uint32(block.number);
    if (operator.snapshot.block == currentBlock) return;

    uint32 blockDiff = currentBlock - operator.snapshot.block;

    // Safe multiplication with overflow check
    uint256 blockDiffFee256 = uint256(blockDiff) * uint256(operator.fee);
    require(blockDiffFee256 <= type(uint64).max, "Fee calculation overflow");
    uint64 blockDiffFee = uint64(blockDiffFee256);

    uint256 balanceIncrease256 = uint256(blockDiffFee) * uint256(operator.validatorCount);
    require(balanceIncrease256 <= type(uint64).max, "Balance calculation overflow");

    operator.snapshot.index += blockDiffFee;
    operator.snapshot.balance += uint64(balanceIncrease256);
    operator.snapshot.block = currentBlock;
}
```

